import{_ as s,l as n,o as a,c as i,v as t,p as l,x as r,d as c,i as d,S as p}from"./chunks/framework.InCnrqk-.js";const u=JSON.parse('{"title":"MTTF 与冗余","description":"","frontmatter":{"title":"MTTF 与冗余","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/mttf-redundancy.md","filePath":"cs/mttf-redundancy.md","lastUpdated":1789023840000}'),h={name:"cs/mttf-redundancy.md"};function E(m,e,T,C,f,A){const o=n("Mermaid");return a(),i("div",null,[e[1]||(e[1]=t('<h1 id="mttf-与冗余" tabindex="-1">MTTF 与冗余 <a class="header-anchor" href="#mttf-与冗余" aria-label="Permalink to &quot;MTTF 与冗余&quot;">​</a></h1><div class="epigraph"><p>软错误和老化让单颗 SRAM 单元不再「永远正确」；用 ECC、锁步、检错重试把故障变成可检测事件，平均无故障时间才回到可接受区。</p><footer>—— 据 Hennessy and Patterson, CA:AQA 可靠性章；Siewiorek 等对容错计算的论述 整理</footer></div><p><a href="/cs/gem5-simulation">上一课</a> 默认无故障。<a href="/cs/dram-refresh">DRAM 刷新</a> 已暗示存储会丢电荷。本课不重讲模拟器统计。缺口是 <strong>MTTF：故障率、串并联、以及微结构常用冗余（ECC、奇偶、锁步）。</strong> 后课的 Rowhammer 是故障被诱导的特例，先把随机故障钉住。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>cache 与 PRF 的位翻转会让看起来精确的 <a href="/cs/retire-precise-exception">退休</a> 写出错架构状态。服务器要求年故障率极低。缺口不是加一层预取，而是<strong>用编码与重复换 MTTF</strong>：检测则回滚到检查点或毒化行；纠正则对软件透明。</p><p><span class="marginnote">FIT（每十亿小时故障）累加：容量越大、电压越低，FIT 越高。ECC DIMM、L2/L3 ECC、寄存器奇偶是工业默认。锁步双核用于更高安全完整性。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>ECC：数据行加冗余位，纠正单比特、检测双比特（典型 SECDED）。奇偶：检测，不能纠正。锁步：两核跑同一指令流，分歧则错。检查点：与<a href="/cs/speculation-recovery">推测恢复</a> 同源，但是架构级的定期快照。</p>',8)),(a(),l(p,null,{default:r(()=>[d(o,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20FIT%5B%22%E5%99%A8%E4%BB%B6%20FIT%20%C3%97%20%E5%AE%B9%E9%87%8F%22%5D%20--%3E%20MTTF%5B%22%E4%B8%B2%E5%B9%B6%E8%81%94%E5%85%AC%E5%BC%8F%22%5D%0A%20%20ECC%5B%22ECC%22%5D%20--%3E%20DET%5B%22%E7%BA%A0%E6%AD%A3%E6%88%96%E6%AF%92%E5%8C%96%22%5D%0A%20%20LOCK%5B%22%E9%94%81%E6%AD%A5%22%5D%20--%3E%20CMP%5B%22%E6%AF%94%E8%BE%83%E8%BE%93%E5%87%BA%22%5D%0A"})]),fallback:r(()=>[...e[0]||(e[0]=[c(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>与性能：ECC 占带宽与延迟，Roofline 的 \\(B\\) 略降。与安全：随机 FIT 不是 Spectre；Rowhammer 是主动打 FIT。本课只要求「微结构必须假设位会翻」。Amdahl 式的可用性：串行维护窗口同样限制。</p><p>检测后的策略：纠正则继续；不可纠正则毒化 cache 行或机器检查异常，精确性回到 <a href="/cs/retire-precise-exception">退休</a>——故障要汇报到某条指令，不能让错误值提交。PRF 与 ROB 也需要保护，否则 ECC 只保护了内存。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把航空级形式化验证拉进来。Spectre 下一课从<strong>正确预测路径上的微结构泄露</strong>出发，不是 FIT。不要在本课写攻击步骤。</p><p>后课默认：随机故障靠 ECC/冗余。推测执行留下的缓存足迹是另一类「正确性」——架构对、微结构泄密。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>MTTF 由 FIT 与冗余结构决定；ECC 是 cache/DRAM 的默认税。</li><li>锁步与检查点服务更高完整性。</li><li>推测执行的缓存副作用是下一课 Spectre。</li><li>出处：Hennessy and Patterson, <em>CA:AQA</em>；Siewiorek。</li></ul>',8))])}const B=s(h,[["render",E]]);export{u as __pageData,B as default};
